import java.util.Arrays;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class PerfGate {
    static String evaluate(long[] samples, long budgetMs) {
        if (samples == null || samples.length == 0 || budgetMs <= 0) {
            throw new IllegalArgumentException("invalid input");
        }
        long[] arr = Arrays.copyOf(samples, samples.length);
        Arrays.sort(arr);
        long p50 = arr[(int) Math.floor(0.5 * (arr.length - 1))];
        long p95 = arr[(int) Math.ceil(0.95 * (arr.length - 1))];
        if (p95 <= budgetMs && p50 <= (long) (budgetMs * 0.6)) {
            return "OK";
        }
        return "SLOW";
    }
}

public class PerfGateTest {
    @Test
    void healthy() {
        assertEquals("OK", PerfGate.evaluate(new long[]{100,120,130,140,150,160,170,180,190,200}, 250));
    }

    @Test
    void slowByP95() {
        assertEquals("SLOW", PerfGate.evaluate(new long[]{100,110,120,130,140,150,160,170,180,800}, 250));
    }

    @Test
    void slowByP50() {
        assertEquals("SLOW", PerfGate.evaluate(new long[]{220,230,240,250,260,270,280,290,300,310}, 400));
    }

    @Test
    void emptyNotAllowed() {
        assertThrows(IllegalArgumentException.class, () -> PerfGate.evaluate(new long[]{}, 100));
    }
}
